import { render, screen, act } from '@testing-library/react';
import { Counter } from '../src/Counter.jsx';

describe('Counter stale-closure interval', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  // REPRODUCTION (regression): the original buggy component reads a stale
  // `count` closure. This test documents that bug — after advancing 3000ms
  // it would read "1" instead of "3".
  it.skip('REPRO: stale closure — reads 1 instead of 3 (kept as regression documentation)', () => {
    const { container } = render(<Counter step={1} />);
    act(() => {
      vi.advanceTimersByTime(3000);
    });
    expect(container.querySelector('[role="timer"]').textContent).toBe('1');
  });

  it('counts to 3 after advancing 3000ms with step=1', () => {
    const { container } = render(<Counter step={1} />);
    act(() => {
      vi.advanceTimersByTime(3000);
    });
    expect(screen.getByRole('timer').textContent).toBe('3');
  });

  it('uses updated step mid-flight and does not leak intervals', () => {
    const clearIntervalSpy = vi.spyOn(globalThis, 'clearInterval');

    const { rerender, unmount } = render(<Counter step={1} />);

    // advance past first tick with step=1 -> count = 1
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(screen.getByRole('timer').textContent).toBe('1');

    // no interval should have been cleared yet (effect not re-run)
    expect(clearIntervalSpy).not.toHaveBeenCalled();

    // change step mid-flight
    rerender(<Counter step={5} />);

    // advance 2 more seconds; each tick adds 5 -> count = 11
    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(screen.getByRole('timer').textContent).toBe('11');

    unmount();

    // cleanup ran exactly once per effect setup: initial + one re-setup = 2
    expect(clearIntervalSpy).toHaveBeenCalledTimes(2);
  });

  it('cleans up its interval exactly once on unmount', () => {
    const clearIntervalSpy = vi.spyOn(globalThis, 'clearInterval');
    const { unmount } = render(<Counter step={1} />);
    expect(clearIntervalSpy).not.toHaveBeenCalled();
    unmount();
    expect(clearIntervalSpy).toHaveBeenCalledTimes(1);
  });
});
"})
