export function Counter({ step }) {
  const [count, setCount] = useState(0);
  // Keep the latest step in a ref so the interval callback never reads a
  // stale prop and the effect doesn't need to tear down/recreate the
  // interval when only `step` changes.
  const stepRef = useRef(step);
  useEffect(() => {
    stepRef.current = step;
  }, [step]);

  useEffect(() => {
    const id = setInterval(() => {
      // Functional update: derive from the current state, not the
      // captured-at-mount `count`, avoiding the stale-closure bug.
      setCount((c) => c + stepRef.current);
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return <span role="timer">{count}</span>;
}
"})
